svg.script:
(function(){
    "use strict";
    var svg=document.getElementById("interactive-floor-lamp");
    var lightOn=false, anchorX=500, anchorY=495, baseLength=78;
    function byId(id){return document.getElementById(id);}
    function setLight(on){lightOn=!!on;svg.setAttribute("data-light-state",lightOn?"on":"off");byId("lamp-shade-hotspot").setAttribute("aria-pressed",lightOn?"true":"false");byId("lamp-pull").setAttribute("aria-pressed",lightOn?"true":"false");byId("lamp-light-overlay").style.opacity=lightOn?"0.62":"0";byId("lamp-light-overlay").style.visibility=lightOn?"visible":"hidden";byId("lamp-light-aura").style.opacity=lightOn?"0.2":"0";byId("lamp-light-aura").style.visibility=lightOn?"visible":"hidden";}
    function toggleLight(){setLight(!lightOn);}
    function setLightColor(color){if(typeof color!=="string"||!color.trim())return false;if(window.CSS&&CSS.supports&&!CSS.supports("color",color))return false;svg.style.setProperty("--lamp-light-color",color.trim());return true;}
    window.setFloorLampLightColor=setLightColor;svg.setFloorLampLightColor=setLightColor;
    svg.addEventListener("design:colorchange",function(event){var detail=event.detail||{};if(detail.property==="--lamp-light-color"||detail.targetSvgId==="lamp-light-overlay")setLightColor(detail.value||detail.color);});
    function localPoint(event){var p=svg.createSVGPoint();p.x=event.clientX;p.y=event.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());}
    function drawChain(extra){var layer=byId("lamp-chain-links");while(layer.firstChild)layer.removeChild(layer.firstChild);var length=baseLength+extra,count=Math.max(4,Math.ceil(length/10)),pitch=length/count;for(var i=0;i<count;i++){var cy=anchorY+(i+.5)*pitch,link=document.createElementNS("http://www.w3.org/2000/svg","ellipse");link.setAttribute("class","chain-link");link.setAttribute("cx",String(anchorX));link.setAttribute("cy",String(cy));link.setAttribute("rx",i%2?"3.2":"3.8");link.setAttribute("ry",String(Math.max(3.2,pitch*.54)));if(i%2)link.setAttribute("transform","rotate(90 "+anchorX+" "+cy+")");layer.appendChild(link);}var ballY=anchorY+baseLength+extra+18;byId("lamp-pull-ball").setAttribute("cy",String(ballY));byId("lamp-pull-highlight").setAttribute("cy",String(ballY-7));byId("lamp-ball-hit").setAttribute("cy",String(ballY));byId("lamp-pull-facets").setAttribute("transform","translate(0 "+extra+")");}
    var group=byId("lamp-pull"),activeId=null,startY=0,maxExtra=0;
    group.addEventListener("pointerdown",function(event){event.preventDefault();activeId=event.pointerId;startY=localPoint(event).y;maxExtra=0;if(group.setPointerCapture){try{group.setPointerCapture(activeId);}catch(e){}}});
    group.addEventListener("pointermove",function(event){if(activeId!==event.pointerId)return;maxExtra=Math.max(maxExtra,Math.max(0,Math.min(145,localPoint(event).y-startY)));drawChain(maxExtra);});
    function release(event,activate){if(activeId!==event.pointerId)return;activeId=null;if(activate)toggleLight();drawChain(0);}
    group.addEventListener("pointerup",function(event){release(event,true);});group.addEventListener("pointercancel",function(event){release(event,false);});group.addEventListener("lostpointercapture",function(event){if(activeId!==null)release(event,false);});
    group.addEventListener("keydown",function(event){if(event.key==="Enter"||event.key===" "){event.preventDefault();toggleLight();}});
    byId("lamp-shade-hotspot").addEventListener("click",toggleLight);byId("lamp-shade-hotspot").addEventListener("keydown",function(event){if(event.key==="Enter"||event.key===" "){event.preventDefault();toggleLight();}});
    setLight(false);drawChain(0);
  })();

(function(){
    "use strict";
    var svg=document.documentElement,ui=document.getElementById("lamp-color-ui");if(!ui)return;
    var channels=[{"key":"shade","label":"Lamp shade","property":"--lamp-shade-color","default":"#ffffff","targetSvgId":"lamp-shade-color-overlay"}],buttons=Array.prototype.slice.call(ui.querySelectorAll(".hh-bubble")),editor=ui.querySelector(".hh-editor"),wheel=ui.querySelector(".hh-wheel"),pointer=ui.querySelector(".hh-wheel-pointer"),value=ui.querySelector(".hh-value"),hex=ui.querySelector(".hh-hex"),rin=ui.querySelector(".hh-r"),gin=ui.querySelector(".hh-g"),bin=ui.querySelector(".hh-b"),close=ui.querySelector(".hh-close"),ctx=wheel.getContext("2d"),active=null,hue=0,sat=0,val=1;
    function clamp(n,a,b){return Math.max(a,Math.min(b,n));}
    function hsv2rgb(h,s,v){var c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c,r=0,g=0,b=0;if(h<60){r=c;g=x;}else if(h<120){r=x;g=c;}else if(h<180){g=c;b=x;}else if(h<240){g=x;b=c;}else if(h<300){r=x;b=c;}else{r=c;b=x;}return [Math.round((r+m)*255),Math.round((g+m)*255),Math.round((b+m)*255)];}
    function rgb2hsv(r,g,b){r/=255;g/=255;b/=255;var mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn,h=0;if(d){if(mx===r)h=60*(((g-b)/d)%6);else if(mx===g)h=60*((b-r)/d+2);else h=60*((r-g)/d+4);}if(h<0)h+=360;return [h,mx?d/mx:0,mx];}
    function toHex(r,g,b){return '#'+[r,g,b].map(function(n){return clamp(Math.round(n),0,255).toString(16).padStart(2,'0');}).join('');}
    function parseColor(c){var m=/^#([0-9a-f]{6})$/i.exec((c||'').trim());if(m)return [parseInt(m[1].slice(0,2),16),parseInt(m[1].slice(2,4),16),parseInt(m[1].slice(4,6),16)];var d=document.createElement('canvas').getContext('2d');d.fillStyle='#000000';try{d.fillStyle=c;}catch(e){}var n=d.fillStyle;if(/^#/.test(n))return parseColor(n);m=/rgb\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\)/.exec(n);return m?[+m[1],+m[2],+m[3]]:[255,255,255];}
    function drawWheel(){var w=wheel.width,h=wheel.height,cx=w/2,cy=h/2,R=Math.min(cx,cy)-2,img=ctx.createImageData(w,h),d=img.data;for(var y=0;y<h;y++)for(var x=0;x<w;x++){var dx=x-cx,dy=y-cy,rr=Math.sqrt(dx*dx+dy*dy),i=(y*w+x)*4;if(rr<=R){var hh=(Math.atan2(dy,dx)*180/Math.PI+360)%360,ss=rr/R,rgb=hsv2rgb(hh,ss,val);d[i]=rgb[0];d[i+1]=rgb[1];d[i+2]=rgb[2];d[i+3]=255;}}ctx.putImageData(img,0,0);var ang=hue*Math.PI/180,rad=sat*R;pointer.style.left=(cx+Math.cos(ang)*rad)+'px';pointer.style.top=(cy+Math.sin(ang)*rad)+'px';}
    function syncFields(color){var rgb=parseColor(color),hsv=rgb2hsv(rgb[0],rgb[1],rgb[2]);hue=hsv[0];sat=hsv[1];val=hsv[2];value.value=String(val);hex.value=toHex(rgb[0],rgb[1],rgb[2]);rin.value=rgb[0];gin.value=rgb[1];bin.value=rgb[2];drawWheel();}
    function buttonFor(prop,key){return buttons.find(function(b){return (prop&&b.dataset.property===prop)||(key&&b.dataset.key===key);});}
    function applyColor(color,emit){if(!active)return;var rgb=parseColor(color),clean=toHex(rgb[0],rgb[1],rgb[2]);svg.style.setProperty(active.dataset.property,clean);active.dataset.color=clean;active.style.background=clean;hex.value=clean;rin.value=rgb[0];gin.value=rgb[1];bin.value=rgb[2];if(emit!==false)svg.dispatchEvent(new CustomEvent('design:colorchange',{bubbles:true,detail:{property:active.dataset.property,key:active.dataset.key,targetSvgId:active.dataset.target,value:clean,color:clean,source:'embedded-color-wheel'}}));}
    function choose(btn){active=btn;buttons.forEach(function(b){b.style.boxShadow=b===btn?'0 0 0 3px #00d7ff,0 0 0 5px #111':'0 0 0 2px #111';});editor.hidden=false;editor.style.display='flex';syncFields(btn.dataset.color||getComputedStyle(svg).getPropertyValue(btn.dataset.property).trim()||'#ffffff');}
    buttons.forEach(function(btn){btn.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();choose(btn);});});
    wheel.addEventListener('pointerdown',function(e){if(!active)return;e.preventDefault();wheel.setPointerCapture&&wheel.setPointerCapture(e.pointerId);moveWheel(e);});wheel.addEventListener('pointermove',function(e){if(e.buttons||e.pressure>0)moveWheel(e);});
    function moveWheel(e){var r=wheel.getBoundingClientRect(),x=(e.clientX-r.left)*wheel.width/r.width,y=(e.clientY-r.top)*wheel.height/r.height,cx=wheel.width/2,cy=wheel.height/2,dx=x-cx,dy=y-cy,R=Math.min(cx,cy)-2,rr=Math.sqrt(dx*dx+dy*dy);sat=clamp(rr/R,0,1);hue=(Math.atan2(dy,dx)*180/Math.PI+360)%360;var rgb=hsv2rgb(hue,sat,val);applyColor(toHex(rgb[0],rgb[1],rgb[2]),true);drawWheel();}
    value.addEventListener('input',function(){val=+value.value;var rgb=hsv2rgb(hue,sat,val);applyColor(toHex(rgb[0],rgb[1],rgb[2]),true);drawWheel();});
    function numeric(){var r=clamp(+rin.value||0,0,255),g=clamp(+gin.value||0,0,255),b=clamp(+bin.value||0,0,255),c=toHex(r,g,b);syncFields(c);applyColor(c,true);}rin.addEventListener('change',numeric);gin.addEventListener('change',numeric);bin.addEventListener('change',numeric);
    hex.addEventListener('change',function(){if(/^#[0-9a-f]{6}$/i.test(hex.value.trim())){syncFields(hex.value.trim());applyColor(hex.value.trim(),true);}});
    Array.prototype.slice.call(ui.querySelectorAll('.hh-preset')).forEach(function(p){p.addEventListener('click',function(){syncFields(p.dataset.color);applyColor(p.dataset.color,true);});});
    close.addEventListener('click',function(){editor.hidden=true;editor.style.display='none';});
    svg.addEventListener('design:colorchange',function(e){var d=e.detail||{},b=buttonFor(d.property,d.key);if(!b||d.source==='embedded-color-wheel')return;var c=d.value||d.color;if(!c)return;var rgb=parseColor(c),clean=toHex(rgb[0],rgb[1],rgb[2]);svg.style.setProperty(b.dataset.property,clean);b.dataset.color=clean;b.style.background=clean;if(active===b)syncFields(clean);});
    svg.setDesignColor=function(keyOrProperty,color){var b=buttonFor(keyOrProperty,keyOrProperty);if(!b)return false;active=b;syncFields(color);applyColor(color,true);return true;};
  })()

(function(){
  var svg=document.documentElement;
  var cfg=window.__hhGeoBubbleConfig;
  if(!cfg)return;
  var wrap=document.getElementById(cfg.wrapId), ui=document.getElementById(cfg.uiId);
  if(!wrap||!ui)return;
  var editor=ui.querySelector('.hh-editor');
  var channels=Array.prototype.slice.call(ui.querySelectorAll('.hh-channel'));
  var buttons=Array.prototype.slice.call(ui.querySelectorAll('.hh-bubble'));
  var activeKey=null;
  function hideEditor(){ if(editor){editor.hidden=true;editor.style.display='none';} }
  function hideAll(){
    wrap.style.display='none'; wrap.style.pointerEvents='none'; activeKey=null; hideEditor();
    channels.forEach(function(c){c.style.display='none';});
  }
  function showFor(key){
    activeKey=key; hideEditor();
    channels.forEach(function(c){
      var b=c.querySelector('.hh-bubble');
      c.style.display=(b&&b.dataset.key===key)?'flex':'none';
    });
    wrap.style.display=''; wrap.style.pointerEvents='auto';
  }
  function isTrigger(el){ return el && el.nodeType===1 && el.hasAttribute('data-geojson-bubble-key'); }
  cfg.triggers.forEach(function(t){
    var el=document.getElementById(t.id); if(!el)return;
    el.setAttribute('data-geojson-bubble-key',t.key);
    el.setAttribute('data-geojson-overlay','true');
    if(!el.getAttribute('tabindex'))el.setAttribute('tabindex','0');
    if(!el.getAttribute('role'))el.setAttribute('role','button');
    if(!el.getAttribute('aria-label'))el.setAttribute('aria-label','Edit '+t.label+' color');
    el.style.pointerEvents='all'; el.style.cursor='pointer';
    el.addEventListener('click',function(e){ showFor(t.key); });
    el.addEventListener('keydown',function(e){
      if(e.key==='Enter'||e.key===' '){ e.preventDefault(); showFor(t.key); }
    });
  });
  ui.addEventListener('click',function(e){e.stopPropagation();});
  svg.addEventListener('click',function(e){
    if(isTrigger(e.target) || (e.target.closest&&e.target.closest('#'+cfg.uiId))) return;
    hideAll();
  });
  var close=ui.querySelector('.hh-close');
  if(close) close.addEventListener('click',function(){ hideAll(); });
  // Only a mapped GeoJSON surface may reveal a bubble. Programmatic color updates never reveal UI.
  hideAll();
})();

(function(){
  var root=document.documentElement;
  if(root.__hhShellBridgeInstalled)return;root.__hhShellBridgeInstalled=true;
  var NS='http://www.w3.org/2000/svg';
  var st=document.createElementNS(NS,'style');
  st.textContent='foreignObject[id$="-color-ui-wrap"],foreignObject[id*="color-ui-wrap"]{display:none!important;visibility:hidden!important;pointer-events:none!important}';
  root.appendChild(st);
  function safe(s){return String(s||'region').replace(/[^a-zA-Z0-9_-]/g,'_')}
  function propertyFor(el,key){
    if(el&&el.dataset&&el.dataset.editableColorProperty)return el.dataset.editableColorProperty;
    var b=document.querySelector('[data-key="'+CSS.escape(String(key||''))+'"][data-property]');
    return b?b.dataset.property:'';
  }
  document.addEventListener('click',function(ev){
    var el=ev.target&&ev.target.closest?ev.target.closest('[data-geojson-bubble-key],[data-editable-color-property],[data-design-region]'):null;
    if(!el)return;
    var key=(el.dataset&&(el.dataset.geojsonBubbleKey||el.dataset.designRegion))||'';
    var prop=propertyFor(el,key);
    parent.postMessage({source:'hh-svg-object',type:'select',objectId:root.dataset.designObjectId||root.id||'',key:key,property:prop},'*');
  },true);
  root.addEventListener('design:colorchange',function(ev){
    var d=ev.detail||{};
    if(d.source==='happy-home-shell')return;
    parent.postMessage({source:'hh-svg-object',type:'color',objectId:root.dataset.designObjectId||root.id||'',key:d.key||'',property:d.property||'',value:d.value||d.color||''},'*');
  });
  function removeTexture(region){
    var old=document.getElementById('hh-shell-pattern-layer-'+safe(region));if(old)old.remove();
    var pat=document.getElementById('hh-shell-pattern-'+safe(region));if(pat)pat.remove();
  }
  function applyTexture(d){
    var region=d.region||d.key||'';if(!region)return;removeTexture(region);if(!d.dataUri)return;
    var defs=root.querySelector('defs');if(!defs){defs=document.createElementNS(NS,'defs');root.insertBefore(defs,root.firstChild)}
    var pid='hh-shell-pattern-'+safe(region),pat=document.createElementNS(NS,'pattern');pat.id=pid;pat.setAttribute('patternUnits','userSpaceOnUse');
    var scale=Math.max(.2,Math.min(8,Number(d.scale)||1)),size=250*scale;
    pat.setAttribute('x',Number(d.offsetX)||0);pat.setAttribute('y',Number(d.offsetY)||0);pat.setAttribute('width',size);pat.setAttribute('height',size);pat.setAttribute('patternTransform','rotate('+(Number(d.rotation)||0)+')');
    var im=document.createElementNS(NS,'image');im.setAttribute('href',d.dataUri);im.setAttribute('x','0');im.setAttribute('y','0');im.setAttribute('width',size);im.setAttribute('height',size);im.setAttribute('preserveAspectRatio','none');pat.appendChild(im);defs.appendChild(pat);
    var layer=document.createElementNS(NS,'g');layer.id='hh-shell-pattern-layer-'+safe(region);layer.setAttribute('pointer-events','none');layer.style.mixBlendMode='multiply';layer.style.opacity=String(Math.max(0,Math.min(1,(d.textureOpacity==null ? .7 : Number(d.textureOpacity)))));
    document.querySelectorAll('[data-design-region="'+CSS.escape(region)+'"]').forEach(function(el){var c=el.cloneNode(true);c.removeAttribute('id');c.removeAttribute('data-geojson-bubble-key');c.removeAttribute('data-editable-color-property');c.setAttribute('fill','url(#'+pid+')');c.setAttribute('pointer-events','none');layer.appendChild(c)});
    var overlay=document.querySelector('[id$="geojson-color-overlays"],[id*="color-overlays"]');(overlay&&overlay.parentNode?overlay.parentNode:root).appendChild(layer);
  }
  window.addEventListener('message',function(ev){
    var d=ev.data||{};if(d.source!=='happy-home-room'||d.type!=='hh-svg-design')return;
    if(d.action==='color'){
      root.dispatchEvent(new CustomEvent('design:colorchange',{bubbles:true,detail:{property:d.property||'',key:d.key||'',value:d.value||d.color||'#ffffff',color:d.value||d.color||'#ffffff',source:'happy-home-shell'}}));
    }else if(d.action==='texture')applyTexture(d);
  });
})();
